// 🌳 노드 생성 함수
function createNode(value) {
  return {
    value,
    left: null,
    right: null
  };
}

// 🌱 트리에 값 삽입
function insertNode(root, value) {
  if (root === null) return createNode(value);

  if (value < root.value) {
    root.left = insertNode(root.left, value);
  } else if (value > root.value) {
    root.right = insertNode(root.right, value);
  }
  // 중복값은 삽입하지 않음
  return root;
}

// 🔍 값 검색 - 해당 값의 노드 반환
function findNode(root, value) {
  if (!root) return null;
  if (value === root.value) return root;
  if (value < root.value) return findNode(root.left, value);
  return findNode(root.right, value);
}

// ❓ 값 포함 여부 반환 (true/false)
function containsValue(root, value) {
  return !!findNode(root, value);
}

// 🔁 BFS (너비 우선 탐색)
function bfs(root) {
  const result = [];
  const queue = [];
  if (root) queue.push(root);

  while (queue.length > 0) {
    const node = queue.shift();
    result.push(node.value);
    if (node.left) queue.push(node.left);
    if (node.right) queue.push(node.right);
  }

  return result;
}

// 🔁 DFS - 전위 순회 (PreOrder: 루트 → 왼쪽 → 오른쪽)
function dfsPreOrder(node, result = []) {
  if (!node) return result;
  result.push(node.value);
  dfsPreOrder(node.left, result);
  dfsPreOrder(node.right, result);
  return result;
}

// 🔁 DFS - 중위 순회 (InOrder: 왼쪽 → 루트 → 오른쪽)
function dfsInOrder(node, result = []) {
  if (!node) return result;
  dfsInOrder(node.left, result);
  result.push(node.value);
  dfsInOrder(node.right, result);
  return result;
}

// 🔁 DFS - 후위 순회 (PostOrder: 왼쪽 → 오른쪽 → 루트)
function dfsPostOrder(node, result = []) {
  if (!node) return result;
  dfsPostOrder(node.left, result);
  dfsPostOrder(node.right, result);
  result.push(node.value);
  return result;
}

